.report-footer{display:none}
.erp-grid{display:grid;grid-template-columns:360px 1fr;gap:18px;align-items:start}.erp-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px}.erp-stat{background:#fff;border:1.5px solid var(--border);border-radius:var(--radius);padding:15px;box-shadow:var(--shadow-sm)}.erp-stat span{display:block;font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.07em;color:var(--text-muted)}.erp-stat strong{display:block;margin-top:5px;font:700 20px 'Lora',serif;color:var(--text)}.erp-stat.green strong{color:var(--green)}.erp-stat.amber strong{color:var(--amber)}
.erp-form{padding:18px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{display:flex;flex-direction:column;gap:5px}.field.full{grid-column:1/-1}.field label{font-size:10px;text-transform:uppercase;letter-spacing:.06em;font-weight:900;color:var(--text-mid)}.inp{width:100%;padding:10px 11px;border:1.5px solid var(--border);border-radius:8px;background:#f8fafc;color:var(--text);font:700 13px 'Nunito',sans-serif}.inp:focus{outline:none;border-color:var(--primary);box-shadow:0 0 0 3px rgba(15,118,110,.1)}textarea.inp{min-height:76px;resize:vertical}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:15px}.alert{padding:11px 14px;border-radius:8px;margin-bottom:15px;font-size:12px;font-weight:800}.alert.success{background:var(--green-lt);color:var(--green);border:1px solid #86efac}.alert.error{background:var(--red-lt);color:var(--red);border:1px solid #fca5a5}.alert.warning{background:var(--amber-lt);color:var(--amber);border:1px solid #fcd34d}
.status-pill{display:inline-flex;align-items:center;gap:5px;padding:3px 9px;border-radius:20px;font-size:10px;font-weight:900;text-transform:uppercase}.status-pill.active,.status-pill.received,.status-pill.paid{background:var(--green-lt);color:var(--green)}.status-pill.draft,.status-pill.partial{background:var(--amber-lt);color:var(--amber)}.status-pill.unpaid,.status-pill.cancelled{background:var(--red-lt);color:var(--red)}.money{white-space:nowrap;font-weight:900}.muted{color:var(--text-muted);font-size:11px}.table-actions{display:flex;gap:5px}.btn-small{display:inline-flex;align-items:center;gap:5px;padding:6px 9px;border-radius:7px;border:1px solid var(--border);background:#fff;color:var(--text-mid);font-size:11px;font-weight:900;text-decoration:none;cursor:pointer}.btn-small:hover{border-color:var(--primary);color:var(--primary)}
.filter-row{display:flex;gap:10px;align-items:end;flex-wrap:wrap;padding:14px 18px}.filter-row .field{min-width:150px;flex:1}.purchase-lines{min-width:820px}.purchase-lines input,.purchase-lines select{width:100%;padding:8px;border:1px solid var(--border);border-radius:6px;font:700 12px 'Nunito',sans-serif}.purchase-lines .qty{width:90px}.purchase-lines .cost{width:140px}.line-total{text-align:right;white-space:nowrap;font-weight:900}.remove-line{border:0;background:var(--red-lt);color:var(--red);width:30px;height:30px;border-radius:6px;cursor:pointer}.totals-box{margin-left:auto;width:min(390px,100%);padding:15px 18px}.total-row-flex{display:flex;justify-content:space-between;align-items:center;padding:6px 0;font-size:13px;font-weight:800}.total-row-flex.grand{border-top:2px solid var(--text);margin-top:5px;padding-top:10px;font-size:18px;font-family:'Lora',serif}.quick-links{display:flex;gap:8px;flex-wrap:wrap}
@media(max-width:1000px){.erp-grid{grid-template-columns:1fr}.erp-stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.erp-stats,.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}.content{padding:14px}.erp-stat strong{font-size:17px}}
